import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

const api = await import('../../src/core/apk-rng.js').catch(error => {
  if (error.code === 'ERR_MODULE_NOT_FOUND') return {};
  throw error;
});
const oracle = JSON.parse(readFileSync(new URL('../../scripts/reference-rng/fixtures.json', import.meta.url))).values;

// These values are generated by the independently built pinned LuaJIT runtime,
// executing only the uploaded APK's original RNG functions outside the repo.
test('APK random module matches every native LuaJIT reference trace value exactly', () => {
  assert.equal(typeof api.createApkRng, 'function', 'APK RNG implementation is missing');
  const actual = {};
  let global = api.createApkMathState();
  for (let i = 1; i <= 5; i++) {
    const next = api.nextApkMathRandom(global);
    actual[`default_random:${i}`] = next.value; global = next.state;
  }
  for (const seed of [0, 0.5, 1, 42, -1]) {
    global = api.createApkMathState(seed);
    for (let i = 1; i <= 5; i++) {
      const next = api.nextApkMathRandom(global);
      actual[`random:${seed}:${i}`] = next.value; global = next.state;
    }
  }
  for (const seed of Object.keys(oracle).filter(key => key.endsWith(':hash')).map(key => key.slice(0, -5))) {
    let rng = api.createApkRng(seed);
    actual[`${seed}:hash`] = api.apkPseudoHash(seed);
    let step = 0;
    for (const key of ['cdt1', 'rarity1sho', 'cdt1', 'pack_generic1', 'cdt1']) {
      const prefix = `${seed}:step${++step}:${key}`;
      const nextSeed = api.nextApkSeed(rng, key);
      actual[`${prefix}:seed`] = nextSeed.value;
      actual[`${prefix}:state`] = nextSeed.rng.streams[key];
      const next = api.nextApkRandom(rng, key);
      actual[`${prefix}:random`] = next.value; rng = next.rng;
      const unkeyed = api.nextApkRandom(rng, undefined, 1, 2);
      actual[`${prefix}:unkeyed_firstpack`] = unkeyed.value; rng = unkeyed.rng;
    }
    actual[`${seed}:prediction`] = api.predictApkSeed('cdt1', seed);
    actual[`${seed}:prediction_state_unchanged`] = rng.streams.cdt1;
    actual[`${seed}:seed_key_unkeyed`] = api.nextApkSeed(rng, 'seed').value;
  }
  for (const key of Object.keys(oracle).filter(key => key.startsWith('format13:'))) {
    actual[key] = api.apkNormalizeStream(Number(key.slice('format13:'.length)));
  }
  assert.deepEqual(actual, oracle);
});

test('APK key streams and global generator survive JSON save/restore without mutation', () => {
  const original = api.createApkRng('PIERROT1');
  const before = JSON.stringify(original);
  const first = api.nextApkRandom(original, 'cdt1');
  assert.equal(JSON.stringify(original), before);
  const restored = JSON.parse(JSON.stringify(first.rng));
  for (const key of [undefined, 'rarity1sho', 'cdt1', 'seed', undefined]) {
    assert.deepEqual(api.nextApkRandom(restored, key), api.nextApkRandom(first.rng, key));
  }
  assert.equal(api.predictApkSeed('cdt1', original.seed), api.nextApkSeed(original, 'cdt1').value);
  assert.equal(JSON.stringify(original), before);
});

test('APK random direct fractional seed and inclusive bounds preserve original semantics', () => {
  const rng = api.createApkRng('PIERROT1');
  const draw = api.nextApkRandom(rng, 0.5);
  assert.equal(draw.value, oracle['random:0.5:1']);
  assert.equal(api.nextApkRandom(rng, 0.5, 1, 2).value, 1);
  assert.equal(api.nextApkRandom(rng, 42, 5, 5).value, 5);
  assert.equal(api.nextApkMathRandom(api.createApkMathState(42), 6).value, 6);
});

test('APK RNG treats reserved JavaScript object names as ordinary independent keys', () => {
  for (const key of ['constructor', '__proto__', 'toString']) {
    const rng = api.createApkRng('PIERROT1');
    const next = api.nextApkSeed(rng, key);
    assert.equal(next.value, api.predictApkSeed(key, rng.seed));
    assert.equal(Object.hasOwn(next.rng.streams, key), true);
    assert.equal(Number.isFinite(next.value), true);
    assert.equal(Object.keys(rng.streams).length, 0);
  }
});

test('APK RNG rejects incompatible or corrupt saved state and non-finite seed/bounds', () => {
  for (const seed of [undefined, '', 42, null]) assert.throws(() => api.createApkRng(seed), TypeError);
  for (const seed of [NaN, Infinity, -Infinity, '42']) assert.throws(() => api.createApkMathState(seed), TypeError);
  const rng = api.createApkRng('PIERROT1');
  for (const state of [null, {}, { ...rng, algorithm: 'counter32-v1' }, { ...rng, mathState: ['no'] }, { ...rng, streams: { cdt1: NaN } }]) {
    assert.throws(() => api.nextApkRandom(state, 'cdt1'), TypeError);
  }
  assert.throws(() => api.nextApkRandom(rng, NaN), TypeError);
  assert.throws(() => api.nextApkRandom(rng, null), TypeError);
  assert.throws(() => api.nextApkRandom(rng, undefined, 3, 2), RangeError);
  assert.throws(() => api.nextApkMathRandom(rng.mathState, Infinity), RangeError);
  assert.throws(() => api.nextApkMathRandom(rng.mathState, 0), RangeError);
});

test('APK RNG initialization can preserve the existing process-global random state', () => {
  const next = api.nextApkMathRandom(api.createApkMathState(42));
  const rng = api.createApkRng('PIERROT1', next.state);
  assert.equal(api.nextApkRandom(rng).value, oracle['random:42:2']);
  assert.notEqual(rng.mathState, next.state);
});

test('APK wrapper ignores a lone bound while LuaJIT math.random retains its one-bound API', () => {
  const rng = api.createApkRng('PIERROT1');
  assert.equal(api.nextApkRandom(rng, 42, 6).value, oracle['random:42:1']);
  assert.doesNotThrow(() => api.validateApkRng(rng));
  assert.throws(() => api.validateApkRng({ ...rng, mathState: ['no'] }), TypeError);
});
